// Writes components/icons.tsx: the app's icons as pixel art, from pixelarticons
// (halfmage/pixelarticons, MIT — notice kept in the generated file and THIRD_PARTY_NOTICES.md).
// Each icon keeps the lucide-react name it replaced, so features import "@/components/icons".
// Re-run after changing the map:   node scripts/make-pixel-icons.mjs [folder with the .svg files]
// (without a folder the SVGs are fetched from GitHub at the pinned commit).
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const COMMIT = "c9ecc2da61afde85dbe539025e3d931c6152ad75"; // pixelarticons master, 2026-10-06
const RAW = `https://raw.githubusercontent.com/halfmage/pixelarticons/${COMMIT}/svg`;

/** Our name → pixelarticons file. */
const MAP = {
  AlertTriangle: "warning-diamond",
  ArrowDown: "arrow-down",
  ArrowLeft: "arrow-left",
  ArrowRight: "arrow-right",
  ArrowUp: "arrow-up",
  Ban: "cancel",
  Bot: "robot",
  Brain: "lightbulb",
  Building2: "building",
  CalendarDays: "calendar-2",
  Check: "check",
  ChevronDown: "chevron-down",
  ChevronLeft: "chevron-left",
  ChevronRight: "chevron-right",
  Code2: "code",
  Copy: "copy",
  ExternalLink: "external-link",
  File: "file",
  FileDown: "download",
  FileText: "file-text",
  Folder: "folder",
  GripVertical: "drag-and-drop",
  History: "clock",
  Info: "info-box",
  KeyRound: "key",
  Languages: "languages",
  Link2: "link",
  ListChecks: "list-box",
  Loader2: "loader",
  LogOut: "logout",
  Maximize: "expand",
  Menu: "menu",
  MessageSquare: "message",
  Mic: "mic",
  Minus: "minus",
  Monitor: "monitor",
  Moon: "moon",
  Network: "git-branch",
  OctagonAlert: "square-alert",
  OctagonX: "stop",
  PanelLeftClose: "chevron-left-2",
  PanelLeftOpen: "chevron-right-2",
  Paperclip: "attachment",
  Pause: "pause",
  Pencil: "pencil",
  Pin: "bookmark",
  PinOff: "bookmark",
  Play: "play",
  Plug: "plug",
  Plus: "plus",
  RefreshCw: "reload",
  RotateCcw: "undo",
  Save: "save",
  Search: "search",
  Send: "send",
  Settings: "settings-cog",
  Settings2: "sliders",
  ShieldAlert: "shield",
  ShieldCheck: "shield",
  Sparkles: "sparkles",
  Square: "stop-solid",
  SquarePen: "pen-square",
  Sun: "sun",
  Trash2: "trash",
  UserPlus: "user-plus",
  WifiOff: "wifi",
  X: "close",
};

const local = process.argv[2];
async function load(file) {
  if (local) return readFileSync(join(local, `${file}.svg`), "utf8");
  const response = await fetch(`${RAW}/${file}.svg`);
  if (!response.ok) throw new Error(`${file}: ${response.status}`);
  return response.text();
}

const paths = {};
for (const file of new Set(Object.values(MAP))) {
  const svg = await load(file);
  const d = [...svg.matchAll(/<path[^>]*\sd="([^"]+)"/g)].map((m) => m[1]);
  if (!d.length || /<(?!svg|\/svg|path)[a-z]/i.test(svg.replace(/<\?xml[^>]*>/, ""))) {
    throw new Error(`${file}: expected only <path> elements`);
  }
  paths[file] = d.join(" ");
}

const lines = Object.entries(MAP)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([name, file]) => `export const ${name} = icon("${name}", "${paths[file]}");`);

writeFileSync(
  new URL("../components/icons.tsx", import.meta.url),
  `// GENERATED by scripts/make-pixel-icons.mjs — do not edit by hand.
// Pixel icons from pixelarticons ${COMMIT.slice(0, 7)} (https://github.com/halfmage/pixelarticons)
// MIT License, Copyright (c) 2019 Gerrit Halfmann. Names follow the lucide-react icons they replaced.
import type { ComponentType, SVGProps } from "react";

import { cn } from "@/lib/utils";

export type IconProps = Omit<SVGProps<SVGSVGElement>, "children">;
export type IconComponent = ComponentType<IconProps>;

/** Small requests (size-2…3.5) get the 12 px size; everything else 24 px — whole art pixels only. */
const SMALL = /(^|\\s)size-(2|2\\.5|3|3\\.5)(\\s|$)/;

function icon(name: string, d: string): IconComponent {
  function Icon({ className, ...props }: IconProps) {
    const small = SMALL.test(className ?? "");
    return (
      <svg
        viewBox="0 0 24 24"
        width={small ? 12 : 24}
        height={small ? 12 : 24}
        fill="currentColor"
        shapeRendering="crispEdges"
        aria-hidden="true"
        focusable="false"
        data-icon={name}
        {...props}
        className={cn(small ? "px-icon-sm" : "px-icon", className?.replace(/(^|\\s)size-[\\d.]+(?=\\s|$)/g, " "))}
      >
        <path d={d} />
      </svg>
    );
  }
  Icon.displayName = name;
  return Icon;
}

${lines.join("\n")}
`,
);
console.log(`components/icons.tsx: ${Object.keys(MAP).length} icons`);
